te-lab{display:grid;grid-template-columns:repeat(3,1fr);gap:26px;align-items:start}.sample{display:flex;flex-direction:column;align-items:center;gap:20px;min-width:0}.sample small{font-size:12px;color:var(--muted)}.node{width:min(100%,146px);aspect-ratio:1;padding:14px;position:relative;background:#18242a;border:1px solid #627883;clip-path:polygon(13% 0,87% 0,100% 13%,100% 87%,87% 100%,13% 100%,0 87%,0 13%);transition:background .18s,border-color .18s}.node:hover{background:#26353d;border-color:#c2d4d8}.node img{width:100%;height:100%;object-fit:contain}.node.selected{border:2px solid #a5c5ce}.node.selected:before{content:'✓';position:absolute;right:13px;top:7px;z-index:2;font-size:18px}.node.focused:after{content:'';position:absolute;inset:8px;border:2px solid var(--ivory);clip-path:polygon(0 0,23% 0,23% 4%,4% 4%,4% 23%,0 23%,0 0,100% 100%,77% 100%,77% 96%,96% 96%,96% 77%,100% 77%,100% 100%);pointer-events:none}.node:focus-visible{outline:0;box-shadow:inset 0 0 0 4px #ddd9c7}.lab-note{grid-column:1/-1;font-size:13px;color:var(--muted)}.lab-live{font-size:14px;min-height:1.7em;color:#b4cbd1;margin-top:20px}.art-button{display:block;border:0;padding:0;background:none;width:100%;position:relative;text-align:left;overflow:hidden}.art-button:hover{background:none}.art-button img{width:100%;transition:transform .45s cubic-bezier(.2,.7,.3,1)}.art-button:hover img{transform:scale(1.012)}.zoom-label{position:absolute;right:14px;bottom:14px;background:rgba(8,14,17,.94);border:1px solid #53636a;padding:6px 12px;font-size:12px;pointer-events:none}.wide-image{border:1px solid var(--line)}figcaption{color:var(--muted);font-size:14px;line-height:1.6;margin-top:16px;max-width:85ch}.tag{display:inline-block;font-size:11px;letter-spacing:.12em;text-transform:uppercase;border:1px solid #49606a;padding:5px 11px;margin-bottom:25px;color:#bacbd0}.proposal{border-color:#75684c;color:#c3b394}.detail-grid{display:grid;grid-template-columns:1.6fr .7fr;gap:70px;margin-top:65px;align-items:center}.detail-grid.reverse{grid-template-columns:.7fr 1.6fr}.detail-grid p{font-size:17px;color:var(--muted);margin-top:22px}.detail-grid .art-button{border:1px solid var(--line)}.caption-rule{border-left:2px solid #6f929e;padding-left:24px}.status-list{margin-top:50px;border-top:1px solid var(--line)}.status-row{display:grid;grid-template-columns:250px 1fr;gap:40px;padding:25px 0;border-bottom:1px solid var(--line)}.status-row p{color:var(--muted);font-size:17px}.status-row strong{font-weight:400}.outro{margin-top:60px;font:clamp(27px,3vw,42px)/1.35 Georgia,serif;max-width:900px}.section-next{display:flex;justify-content:flex-end;margin-top:50px;font-size:14px;color:#adc3ca}.footer{padding:32px 0;color:var(--muted);font-size:13px}.footer .wrap{display:flex;justify-content:space-between;gap:25px}.reveal{animation:appear .65s both;animation-timeline:view();animation-range:entry 0% entry 20%}@keyframes appear{from{opacity:.55;transform:translateY(20px)}to{opacity:1;transform:none}}dialog{padding:0;border:1px solid #687f88;background:#0c1114;color:var(--ivory);width:min(96vw,1900px);max-width:none;max-height:94svh;overflow:auto}dialog::backdrop{background:rgba(0,0,0,.9)}.dialog-head{position:sticky;top:0;background:#101a20;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:14px 20px;z-index:2}.dialog-head h2{font:18px 'Segoe UI',sans-serif;letter-spacing:0;line-height:1.5}.dialog-head button{padding:7px 14px;white-space:nowrap}.dialog-image{width:100%;height:auto}.dialog-caption{padding:18px 24px;color:var(--muted);font-size:15px}
@media(min-width:1000px) and (prefers-reduced-motion:no-preference){.hero-art img{animation:hero-depth linear both;animation-timeline:scroll(root);animation-range:0vh 100vh}@keyframes hero-depth{to{transform:scale(1.25) translateY(6%)}}}
@media(max-width:1000px){.wrap{width:calc(100% - 56px)}.links{gap:15px}.links a span{display:none}.section-head{gap:35px}.section{padding:80px 0}.detail-grid,.detail-grid.reverse{gap:35px}.state-layout{gap:35px;grid-template-columns:1fr}.swatch{padding:14px;height:150px}.icon-band{gap:15px}.principles{gap:24px}}
@media(max-width:640px){body{font-size:16px}.wrap{width:calc(100% - 36px)}.top .wrap{width:calc(100% - 24px)}.nav{gap:12px;min-height:64px}.brand{font-size:17px}.links{gap:12px;font-size:12px}.links a{padding:20px 0}.print{font-size:0;padding:8px}.print:after{content:'⎙';font-size:19px}.hero{min-height:100svh;padding:135px 0 85px}.hero h1{font-size:clamp(54px,12vw,80px)}.hero .lead{font-size:20px}.hero-art img{object-position:62% center}.hero-foot{align-items:flex-start;flex-direction:column;gap:20px}.hero-note{max-width:100%}.section-head{grid-template-columns:1fr;gap:25px;margin-bottom:38px}.section{padding:65px 0}.palette{grid-template-columns:1fr 1fr;margin-top:35px}.swatch{border-right:1px solid #3f5058;height:145px}.swatch:last-child{grid-column:1/-1;height:95px;flex-direction:row;align-items:center}.principles{grid-template-columns:1fr;gap:25px}.icon-band{grid-template-columns:repeat(3,1fr);gap:28px 15px;margin-bottom:45px}.icon-band figcaption{font-size:13px}.state-lab{gap:12px}.node{padding:8px}.sample small{font-size:10px}.detail-grid,.detail-grid.reverse{grid-template-columns:1fr;margin-top:40px;gap:30px}.detail-grid.reverse .caption-rule{order:2}.zoom-label{right:6px;bottom:6px;font-size:10px;padding:4px 7px}.status-row{grid-template-columns:1fr;gap:9px;padding:22px 0}.status-row p{font-size:16px}.footer .wrap{flex-direction:column}.dialog-head{padding:10px;gap:10px}.dialog-head h2{font-size:14px}.dialog-head button{font-size:13px}.dialog-caption{padding:14px}.eyebrow{font-size:11px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation:none!important;transition:none!important}.hero-art img{transform:none}}
